RSpec.describe "Timekeeping handoff checkpoint load run twice" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:load_twice_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => load_twice_token
    ) { example.run }
  end

  before do
    Timekeeping::Admission.ensure_initial!
    Timekeeping::Admission.fence!
  end

  def load_twice_rows(company_id, id)
    at = Time.utc(2026, 3, 2, 9)
    operation_id = SecureRandom.uuid
    {
      "entries" => [{
        "id" => id, "company_id" => company_id, "version" => 2, "project_id" => 10, "user_id" => 20,
        "agent_id" => nil, "work_date" => Date.new(2026, 3, 2), "duration" => 60.0, "note" => "",
        "bill_status" => "unbilled", "review_status" => "not_required", "locked" => true, "source" => "manual",
        "source_metadata" => { "nested" => { "n" => BigDecimal("1.00000000000000000001") } },
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => at, "updated_at" => at
      }],
      "reservations" => [{
        "company_id" => company_id, "entry_id" => id, "invoice_id" => 5, "state" => "committed",
        "disposition" => "active", "operation_id" => operation_id, "created_at" => at
      }],
      "invoice_operations" => [{
        "id" => id, "company_id" => company_id, "invoice_id" => 5, "operation_id" => operation_id,
        "state" => "committed", "desired_entry_ids" => [id], "disposition" => "active", "generation" => 1,
        "created_at" => at, "finished_at" => at
      }],
      "entry_audits" => [{
        "id" => id, "company_id" => company_id, "entry_id" => id, "actor_type" => "user", "actor_id" => 20,
        "action" => "create", "before" => Timekeeping::Handoff::Checkpoint::JSON_NULL,
        "after" => { "duration" => BigDecimal("60.000000000000000001") }, "entry_created_at" => at, "created_at" => at
      }],
      "idempotency_records" => [{
        "id" => id, "company_id" => company_id, "actor_type" => "user", "actor_id" => 20, "operation" => "create",
        "key" => "key-#{id}", "fingerprint" => "fp-#{id}", "status" => 201, "body" => "{}", "created_at" => at
      }]
    }
  end

  def load_twice_put(body)
    put "/internal/v1/handoff/checkpoint", params: body,
                                           headers: { "Authorization" => "Bearer #{load_twice_token}",
                                                      "CONTENT_TYPE" => "application/json" }
    response
  end

  it "loads the same populated two-company checkpoint twice with equal counts and checksums, and exports the same rows back" do
    # Two companies, so a row attached to the wrong company changes the digest. The ids differ because
    # entries.id is the primary key on its own and cannot repeat across companies.
    first = load_twice_rows(1, 7)
    second = load_twice_rows(2, 8)
    tables = first.to_h { |table, rows| [table, rows + second.fetch(table)] }
    checkpoint = Timekeeping::Handoff::Checkpoint.build(tables:)

    # "Load: "replaces the incoming owner's tables in one transaction", so loading the same checkpoint twice gives equal counts and checksums."
    first_load = load_twice_put(checkpoint.to_json)
    expect(first_load.status).to eq(200)
    first_digest = Timekeeping::Handoff::Checkpoint.from_json(first_load.body).digest

    second_load = load_twice_put(checkpoint.to_json)
    expect(second_load.status).to eq(200)
    second_digest = Timekeeping::Handoff::Checkpoint.from_json(second_load.body).digest

    expect(first_digest).to eq(checkpoint.digest)
    expect(second_digest).to eq(first_digest)
    expect([Entry.count, Reservation.count, AuditEvent.count, IdempotencyReceipt.count]).to eq([2, 2, 2, 2])

    get "/internal/v1/handoff/checkpoint", headers: { "Authorization" => "Bearer #{load_twice_token}" }
    expect(response.status).to eq(200)
    exported = Timekeeping::Handoff::Checkpoint.from_json(response.body)
    expect(Timekeeping::Handoff::Checkpoint.verify(exported)).to eq([])
    expect(exported.digest).to eq(checkpoint.digest)
    expect(exported.rows.fetch("entry_audits").map { |row| [row["company_id"], row["id"]] }).to contain_exactly([1, 7], [2, 8])
  end
end

