RSpec.describe "Timekeeping handoff checkpoint load refusals" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:refusal_load_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => refusal_load_token
    ) { example.run }
  end

  before do
    Timekeeping::Admission.ensure_initial!
    Timekeeping::Admission.fence!
  end

  it "refuses a load holding an entry older than the stored one and leaves every table as it was" do
    at = Time.utc(2026, 3, 2, 9)
    Entry.insert_all!([{
      id: 9, company_id: 1, version: 3, project_id: 10, user_id: 20, work_date: Date.new(2026, 3, 2),
      duration: 45.0, bill_status: "unbilled", created_at: at, updated_at: at
    }])
    entry_row = {
      "id" => 9, "company_id" => 1, "version" => 2, "project_id" => 10, "user_id" => 20, "agent_id" => nil,
      "work_date" => Date.new(2026, 3, 2), "duration" => 45.0, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => at, "updated_at" => at
    }
    checkpoint = Timekeeping::Handoff::Checkpoint.build(tables: {
      "entries" => [entry_row], "reservations" => [], "invoice_operations" => [],
      "entry_audits" => [], "idempotency_records" => []
    })

    put "/internal/v1/handoff/checkpoint", params: checkpoint.to_json,
                                           headers: { "Authorization" => "Bearer #{refusal_load_token}",
                                                      "CONTENT_TYPE" => "application/json" }

    # "Refuse any entry whose current version is higher than its checkpoint version."
    expect(response.status).to eq(409)
    expect(response.parsed_body).to eq("reason" => "handoff_refused")
    expect(Entry.pluck(:company_id, :id, :version, :duration)).to eq([[1, 9, 3, 45.0]])
  end
end

