RSpec.describe "Timekeeping handoff correction snapshots" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:correction_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => correction_token
    ) { example.run }
  end

  before do
    Timekeeping::Admission.ensure_initial!
    Timekeeping::Admission.fence!
  end

  it "writing the same corrections twice leaves one snapshot per corrected entry at version 1 and the new generation" do
    at = Time.utc(2026, 3, 2, 9)
    entry = { company_id: 1, version: 0, project_id: 10, user_id: 20, work_date: Date.new(2026, 3, 2),
              duration: 30.0, bill_status: "unbilled", created_at: at, updated_at: at }
    Entry.insert_all!([entry.merge(id: 11), entry.merge(id: 12)])
    snapshots = [11, 12].map do |id|
      (Timekeeping::OutboxFields::ENTRY_FIELDS - ["version"]).index_with { nil }.merge(
        "id" => id, "company_id" => 1, "project_id" => 10, "user_id" => 20, "work_date" => "2026-03-02",
        "duration" => 30.0, "note" => "", "bill_status" => "unbilled", "review_status" => "not_required",
        "locked" => false, "source" => "manual", "source_metadata" => {}, "proof_metadata" => {},
        "created_at" => at.iso8601, "updated_at" => at.iso8601
      )
    end
    body = { generation: 2, version: 1, snapshots: }.to_json
    headers = { "Authorization" => "Bearer #{correction_token}", "CONTENT_TYPE" => "application/json" }

    # "Writing the same corrections again replaces them, so there is never a second snapshot for one entry and generation."
    put "/internal/v1/handoff/correction_snapshots", params: body, headers: headers
    expect(response.status).to eq(200)
    put "/internal/v1/handoff/correction_snapshots", params: body, headers: headers
    expect(response.status).to eq(200)

    # "The first cutover writes one per corrected entry, at version 1 and the new generation."
    expect(OutboxSnapshot.order(:id).pluck(:company_id, :id, :version, :generation, :locked))
      .to eq([[1, 11, 1, 2, false], [1, 12, 1, 2, false]])
  end
end

